#include <iostream>
#include <string>
#include <vector>

// Mô phỏng sự tương tác giữa các đơn vị logic trong C++17
struct SimulatedALU {
    static long long add(long long a, long long b) { return a + b; }
    static bool isEqual(long long a, long long b) { return a == b; }
};

struct SimulatedCPU {
    // Đơn vị bộ nhớ chính (Primary Memory - volatile)
    std::vector<long long> primaryMemory;

    void runProgram(long long operand1, long long operand2) {
        // Đọc dữ liệu từ Input Unit vào Primary Memory
        primaryMemory.push_back(operand1);
        primaryMemory.push_back(operand2);

        // CPU điều phối ALU tính toán
        long long sum = SimulatedALU::add(primaryMemory[0], primaryMemory[1]);
        bool same = SimulatedALU::isEqual(primaryMemory[0], primaryMemory[1]);

        // Output Unit xuất kết quả
        std::cout << "Sum: " << sum << "\n";
        std::cout << "Equal: " << (same ? "true" : "false") << "\n";
    }
};

int main() {
    long long a{0};
    long long b{0};
    if (std::cin >> a >> b) {
        SimulatedCPU cpu;
        cpu.runProgram(a, b);
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <bitset>

// Phân cấp dữ liệu trong C++17:
// 1. Bit -> std::bitset<8>
// 2. Ký tự/Byte -> char
// 3. Trường (Field) -> std::string, int
// 4. Bản ghi (Record) -> struct PersonRecord
// 5. Tệp (File / Collection) -> std::vector<PersonRecord>

struct PersonRecord {
    std::string firstName; // Field 1
    std::string lastName;  // Field 2
};

int main() {
    // Khởi tạo một 'File' chứa các 'Record'
    std::vector<PersonRecord> fileCollection = {
        {"Sally", "Black"},
        {"Judy", "Green"}
    };

    for (const auto& record : fileCollection) {
        std::cout << "Record: " << record.firstName << " " << record.lastName << "\n";
        // Khảo sát ký tự đầu tiên của trường firstName dưới góc độ Byte và Bit
        char firstChar = record.firstName[0];
        std::bitset<8> bits(static_cast<unsigned char>(firstChar));
        std::cout << "  First char: " << firstChar << " (ASCII: " << static_cast<int>(firstChar) 
                  << ", Bits: " << bits << ")\n";
    }
    return 0;
}
